<?php require __DIR__.'/config/config.php'; if(empty($_SESSION['user_id'])||($_SESSION['gender']??'')!=='female'){header('Location:dashboard.php');exit;} $u=db()->prepare('SELECT * FROM users WHERE id=?');$u->execute([$_SESSION['user_id']]);$u=$u->fetch();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$age=(int)$_POST['age'];$hours=trim($_POST['hours']??'');$time=trim($_POST['time_slot']??'');$phone=trim($_POST['phone']??'');$tg=trim($_POST['telegram']??'');$city=trim($_POST['city']??'');if($age<18||!$hours||!$time||!$phone||!$city){$err='Please fill all required details.';}else{$s=db()->prepare('INSERT INTO earning_applications(user_id,age,hours,time_slot,phone,telegram,city) VALUES(?,?,?,?,?,?,?)');$s->execute([$u['id'],$age,$hours,$time,$phone,$tg,$city]);telegram_notify("💰 New Video Calling Earning Application\nName: {$u['name']}\nAge: {$age}\nHours: {$hours}\nTime: {$time}\nPhone: {$phone}\nTelegram: {$tg}\nCity: {$city}");header('Location: earning_success.php');exit;}}
